var paths={confused:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18v1M3 6l3 1M18 5l3-1',weakness:'M12 3v17m-6-6 6 6 6-6M4 4h4m8 0h4',strength:'M12 21V4m-6 6 6-6 6 6M4 20h4m8 0h4',fullness:'M12 20S3 15 3 9a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6-9 11-9 11ZM9 11h6m-3-3v6',regeneration:'M20 8a9 9 0 1 0 1 7M20 3v5h-5M9 12h6m-3-3v6',attrition:'M7 3h10v5l-5 4 5 4v5H7v-5l5-4-5-4ZM8 19h8',fortress:'M4 21V4h4v4h3V4h3v4h3V4h3v17ZM9 21v-6h6v6',exposed:'M12 3 2 21h20ZM12 9v5m0 3v1',relief:'M4 15c4-6 12-6 16 0M7 8l2-2m6 0 2 2M7 19h10',wound:'M7 3h10v4l-3 3 3 3-3 3 3 3v2H7v-4l3-3-3-3 3-3-3-3Z',precision:'M12 2v5m0 10v5M2 12h5m10 0h5M8 8h8v8H8Z',fatigue:'M4 5h16M7 9h10m-7 4h4M12 17v5m-3-3 3 3 3-3'};
