 const p=s.players[victim];if(doc==='aforado'&&!p.saved.includes(c.uid)){p.saved.push(c.uid);c.hp=['actions1','actions2'].includes(s.ruleset)?3:1;log(s,c.name+' conserva el escaño.');return;}
